<script setup>
defineProps({ requests: { type: Array, default: () => [] }, loading: Boolean, processing: Boolean });
defineEmits(["decide"]);

function initials(user) { return `${user?.first_name?.[0] || ""}${user?.last_name?.[0] || ""}`.toUpperCase(); }
function label(status) { return { pending: "En attente", accepted: "Acceptée", cancelled: "Annulée" }[status] || status; }
</script>

<template>
  <div class="requests-card"><div class="requests-heading"><div><h3>Demandes à rejoindre</h3><p>Autorisez les participants avant leur accès à la salle.</p></div><span>{{ requests.filter((request) => request.status === 'pending').length }} en attente</span></div><p v-if="loading" class="empty">Chargement des demandes…</p><p v-else-if="!requests.length" class="empty">Aucune demande pour le moment.</p><div v-else class="request-list"><div v-for="request in requests" :key="request.id" class="request-row"><span class="avatar">{{ initials(request.user) }}</span><div class="request-user"><strong>{{ request.user?.name }}</strong><small>{{ request.user?.email }}</small></div><span class="request-status" :class="request.status">{{ label(request.status) }}</span><div v-if="request.status === 'pending'" class="request-actions"><button type="button" class="accept" :disabled="processing" @click="$emit('decide', request, 'accepted')">Accepter</button><button type="button" class="decline" :disabled="processing" @click="$emit('decide', request, 'cancelled')">Refuser</button></div></div></div></div>
</template>

<style scoped>
.requests-card { margin-top: 1.25rem; padding: 1.25rem; border: 1px solid #e8eef6; border-radius: .9rem; background: #fff; box-shadow: 0 5px 15px rgb(30 52 84 / 3%); }.requests-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 1rem; margin-bottom: 1rem; }.requests-heading h3 { margin: 0; color: #253650; font-size: .9rem; }.requests-heading p { margin: .3rem 0 0; color: #98a5b5; font-size: .7rem; }.requests-heading > span { padding: .35rem .5rem; border-radius: .4rem; color: #a07b2e; background: #fff7df; font-size: .64rem; white-space: nowrap; }.request-list { display: grid; gap: .15rem; }.request-row { display: flex; align-items: center; gap: .7rem; padding: .75rem .25rem; border-top: 1px solid #f0f3f7; }.avatar { display: grid; width: 2rem; height: 2rem; flex: 0 0 auto; place-items: center; border-radius: .6rem; color: #5278d0; background: #eaf1ff; font-size: .6rem; font-weight: 800; }.request-user { min-width: 0; flex: 1; }.request-user strong, .request-user small { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.request-user strong { color: #32425a; font-size: .74rem; }.request-user small { margin-top: .15rem; color: #a4afbd; font-size: .62rem; }.request-status { padding: .28rem .45rem; border-radius: .35rem; color: #a07b2e; background: #fff7df; font-size: .6rem; font-weight: 700; }.request-status.accepted { color: #2f9b73; background: #eaf9f2; }.request-status.cancelled { color: #8995a5; background: #f1f4f7; }.request-actions { display: flex; gap: .4rem; }.request-actions button { padding: .4rem .5rem; border: 0; border-radius: .35rem; font-size: .62rem; font-weight: 700; cursor: pointer; }.accept { color: #fff; background: #43ad82; }.decline { color: #bd5965; background: #fff0f2; }.request-actions button:disabled { cursor: wait; opacity: .55; }.empty { padding: 1.5rem 0 .5rem; color: #9aa7b7; font-size: .74rem; text-align: center; }
@media (max-width: 620px) { .request-row { align-items: flex-start; flex-wrap: wrap; }.request-status { margin-left: auto; }.request-actions { width: 100%; margin-left: 2.7rem; } }
</style>
